export async function sendWebhook(
  text: string,
  opts?: { username?: string; avatarUrl?: string; embeds?: object[] },
): Promise<void> {
  const url = process.env.DISCORD_WEBHOOK_URL;
  if (!url) throw new Error("DISCORD_WEBHOOK_URL not set");
  await fetch(url, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({
      content: text,
      username: opts?.username,
      avatar_url: opts?.avatarUrl,
      embeds: opts?.embeds,
    }),
  });
}

export async function sendEmbed(opts: {
  title: string;
  description?: string;
  color?: number;
  fields?: Array<{ name: string; value: string; inline?: boolean }>;
}): Promise<void> {
  await sendWebhook("", {
    embeds: [
      {
        title: opts.title,
        description: opts.description,
        color: opts.color ?? 0x5865f2,
        fields: opts.fields,
      },
    ],
  });
}
